// The business logo: the one image an invoice carries.
//
// A logo is stored on the business profile as bytes and copied onto every
// invoice created from then on (`Invoice.issuer.logo`), like every other
// figure on the document. What crosses the wire is a data URL for the
// settings screen, a `hasLogo` flag on an invoice, and the `{ mime, base64 }`
// upload. The caps and the refusal codes live here so the upload control, the
// procedure and the importer cannot disagree about what a logo may be; the
// byte-level checks (magic bytes, header fields) are the server's
// `services/invoice-logo.ts`, since they need the bytes.

/** The two formats pdfkit embeds as-is. No SVG (no renderer), no WebP, no GIF. */
export const BUSINESS_LOGO_MIMES = ["image/png", "image/jpeg"] as const;
export type BusinessLogoMime = (typeof BUSINESS_LOGO_MIMES)[number];

/** Decoded file size cap. A logo is a few KB; this leaves room for a photo-like JPEG. */
export const BUSINESS_LOGO_MAX_BYTES = 300 * 1024;

/**
 * Per-side pixel cap. pdfkit decodes a PNG with alpha pixel by pixel to split
 * the mask off, so a 300 KB file that inflates to a huge flat image would cost
 * memory on every render. 2000 px prints sharp at any box an invoice draws.
 */
export const BUSINESS_LOGO_MAX_DIMENSION = 2000;

/** The longest base64 body the upload accepts: the byte cap, encoded. */
export const BUSINESS_LOGO_MAX_BASE64_LENGTH = Math.ceil(BUSINESS_LOGO_MAX_BYTES / 3) * 4;

/**
 * Why an upload was refused, as a stable code the client translates. Each is
 * the `message` of a BAD_REQUEST from `settings.setBusinessLogo`.
 */
export const BUSINESS_LOGO_REFUSALS = {
  /** Not a PNG or JPEG file (by its bytes), whatever the declared type. */
  unsupportedFormat: "logo-unsupported-format",
  /** Over {@link BUSINESS_LOGO_MAX_BYTES}. */
  tooLarge: "logo-too-large",
  /** Wider or taller than {@link BUSINESS_LOGO_MAX_DIMENSION}. */
  tooBig: "logo-too-big",
  /** The header is unreadable, or a side is 0. */
  corrupt: "logo-corrupt",
  /** Adam7 interlacing. */
  interlacedPng: "logo-interlaced-png",
  /** Four-channel JPEG: PDF/A-3b allows one output intent, and it is sRGB. */
  cmykJpeg: "logo-cmyk-jpeg",
  /** 12-bit, lossless or arithmetic-coded JPEG: DCTDecode viewers do not read them. */
  unsupportedJpeg: "logo-unsupported-jpeg",
} as const;

export type BusinessLogoRefusal = (typeof BUSINESS_LOGO_REFUSALS)[keyof typeof BUSINESS_LOGO_REFUSALS];

const REFUSAL_SET: ReadonlySet<string> = new Set(Object.values(BUSINESS_LOGO_REFUSALS));

/** The refusal a BAD_REQUEST message names, or null for any other message. */
export function businessLogoRefusalOf(message: unknown): BusinessLogoRefusal | null {
  return typeof message === "string" && REFUSAL_SET.has(message) ? (message as BusinessLogoRefusal) : null;
}

/** The logo as the settings screen and the export see it. */
export type BusinessLogo = {
  /** `data:image/png;base64,…` — the stored bytes, unchanged. */
  dataUrl: string;
  width: number;
  height: number;
};

/** The upload body: which format the bytes are, and the bytes. */
export type BusinessLogoUpload = { mime: BusinessLogoMime; base64: string };

const DATA_URL = /^data:(image\/png|image\/jpeg);base64,([A-Za-z0-9+/]+={0,2})$/;

/**
 * `{ mime, base64 }` out of a data URL, or null when the string is not one
 * of the two formats as a base64 data URL. Whitespace is not tolerated: a
 * data URL the app wrote never has any, and one that does is not ours.
 */
export function parseImageDataUrl(value: unknown): BusinessLogoUpload | null {
  if (typeof value !== "string" || value.length > BUSINESS_LOGO_MAX_BASE64_LENGTH + 64) return null;
  const match = DATA_URL.exec(value);
  if (!match) return null;
  return { mime: match[1] as BusinessLogoMime, base64: match[2] ?? "" };
}

/** The data URL for a stored logo. */
export function imageDataUrl(upload: BusinessLogoUpload): string {
  return `data:${upload.mime};base64,${upload.base64}`;
}

/** The mime type of a browser `File`, when it is one of the two. */
export function businessLogoMimeOf(type: string): BusinessLogoMime | null {
  return (BUSINESS_LOGO_MIMES as readonly string[]).includes(type) ? (type as BusinessLogoMime) : null;
}
